# Implementation of the sequence definition to verify calculations up to n=15
def solve_a(n, memo):
    if n == 1:
        return 0
    if n in memo:
        return memo[n]

    max_val = -float('inf')
    for i in range(1, n):
        val = solve_a(i, memo) + solve_a(n - i, memo) + min(i, n - i)
        if val > max_val:
            max_val = val

    memo[n] = max_val
    return max_val

a_values = {}
for n in range(1, 16):
    a_values[n] = solve_a(n, a_values)

print("n | a_n")
for n, val in a_values.items():
    print(f"{n:2} | {val}")
